  verb_ctx m m1 sp s0v s1v ra j8 P bs (P + 1) (Z.of_nat (length bs) - 1) lo shi -> verb_pure sp P bs lo shi ->
  bs = b0 :: rest -> (2 <= length rest)%nat -> zb b0 = c ->
