Ltac arm_intro :=
  intros rax a0x a1x a2x ra sp gp tp t0 t1 t2 a3 a4 a5 a6 a7 s0v s1v s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 j8 F fc m m1 P bs lo shi b0 rest;
  intros CTX PURE HBS HL HC;
  pose proof CTX as CTX'; pose proof PURE as PURE'; open_verb CTX' PURE';
  (assert (HLEN : length bs = S (length rest)) by (rewrite HBS; reflexivity));
  lazymatch goal with W : bytes_at _ m1 P bs |- _ =>
    assert (WR : bytes_at bsegs m1 (P + 1) rest) by (rewrite HBS in W; exact (bytes_at_tail _ _ _ _ W)) end;
  unfold wz in *; rewrite ?ASHADOW_BASE_val.

