Ltac bcmp_litw BCMP AX LX k ls Lw P sp :=
  lazymatch goal with
  | SD : verb_side ?m0 ?lo ?shi _ _, CEIL : aceil <= ?lo, WL : bytes_at _ ?mc Lw ls, ST : stk _ ?mc ?lo _, MI : mem_inv _ ?mc,
    MU : munch _ ?m0 ?mc, WM : wmono _ ?m0 ?mc, IMW : in_app_mem P _, SEPW : hideL (_ \/ _) |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    let ACc := fresh "ACc" in let AWc := fresh "AWc" in let SVc := fresh "SVc" in
    let LB := fresh "LB" in let LZ := fresh "LZ" in let LA := fresh "LA" in let LS := fresh "LS" in let LI := fresh "LI" in
    let LR1 := fresh "LR1" in let LR2 := fresh "LR2" in
    destruct (verb_side_now _ mc _ _ _ _ _ SD MU WM CEIL) as (ACc & _ & AWc & SVc);
    destruct (vlit_facts mc AX LX ltac:(vlit_in) MI ACc) as (LB & LZ & LA & LS & LI & LR1 & LR2);
    unfold AX in LB, LA, LS, LI, LR1, LR2;
    replace (Z_to_bv 64 k) with (Z_to_bv 64 (Z.of_nat (length ls))) by (f_equal; lia);
    lazymatch type of LB with bytes_at _ _ ?A _ =>
      callZc (bcmp_icpt_specZ BCMP _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ (bv_unsigned sp + -48) Lw A ls (litb LX) lo)
             (clear ST ACc AWc SVc LB LA LS LI LR1 LR2);
      [ exact WL | exact LB | rewrite length_litb; unfold LX; cbn [length]; lia | lia
      | eapply accessible_sub; [exact AWc | lia | lia | lia]
      | replace (Z.of_nat (length ls)) with (Z.of_nat (length LX)) by (unfold LX; cbn [length]; lia); exact LA
      | eapply shvis_sub; [exact SVc | lia | lia | lia | lia | lia]
      | replace (Z.of_nat (length ls)) with (Z.of_nat (length LX)) by (unfold LX; cbn [length]; lia); exact LS
      | eapply in_app_mem_sub; [exact IMW | lia | lia]
      | replace (Z.of_nat (length ls)) with (Z.of_nat (length LX)) by (unfold LX; cbn [length]; lia); exact LI
      | exact ST | exact CEIL | lia | lia
      | unfold hideL in SEPW; lia
      | left; lia
      | exact MI | exact ACc | ]
    end;
    verb_names sp lo;
    (* [comment removed for export] *)
    verb_rebuild_ctx m0 sp P;
    (* [comment removed for export] *)
    step;
    lazymatch goal with |- evt _ _ (MS _ _ (if ?c then _ else _) _ _ _ _) =>
      rewrite (bcmp_branch ls) by (rewrite length_litb; unfold LX; cbn [length]; lia); rewrite LZ; clear LZ end
  end.
Ltac bcmp_lit BCMP AX LX k rest P sp := bcmp_litw BCMP AX LX k rest (P + 1) P sp.

